// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

contract MedicalRecordAccess {
    enum Role { None, Patient, Doctor, Admin }

    struct PatientInfo {
        string name;
        uint age;
        string gender;
        string nationalId;
    }

    struct DoctorInfo {
        string name;
        string specialization;
        string licenseId;
        string hospitalName;
    }

    struct AdminInfo {
        string name;
        string organization;
    }

    struct Record {
        string ipfsHash;
        address owner;
        bool exists;
    }

    address public systemAdmin;
    uint public recordCount;

    mapping(address => Role) public roles;
    mapping(address => PatientInfo) public patients;
    mapping(address => DoctorInfo) public doctors;
    mapping(address => AdminInfo) public admins;

    mapping(uint => Record) public records;
    mapping(uint => mapping(address => uint)) public accessControl; // recordId -> doctor -> expiry
    mapping(address => uint[]) public doctorAccessibleRecords;

    // ------------------- Events --------------------
    event Registered(address indexed user, Role role);
    event RecordUploaded(uint indexed recordId, address indexed patient, string ipfsHash);
    event AccessGranted(uint indexed recordId, address indexed doctor, uint expiry);
    event AccessRevoked(uint indexed recordId, address indexed doctor);
    event RecordDeleted(uint indexed recordId, address indexed deletedBy);

    // ------------------ Constructor -----------------
    constructor() {
        systemAdmin = msg.sender;
        roles[msg.sender] = Role.Admin;
        admins[msg.sender] = AdminInfo("System Admin", "Default Organization");
    }

    // ------------------ Modifiers --------------------
    modifier onlyAdmin() {
        require(roles[msg.sender] == Role.Admin, "Only admin can do this");
        _;
    }

    modifier onlyPatient() {
        require(roles[msg.sender] == Role.Patient, "Only patient can do this");
        _;
    }

    modifier onlyDoctor() {
        require(roles[msg.sender] == Role.Doctor, "Only doctor can do this");
        _;
    }

    modifier onlyOwner(uint recordId) {
        require(records[recordId].owner == msg.sender, "You are not the owner");
        _;
    }

    modifier recordExists(uint recordId) {
        require(records[recordId].exists, "Record does not exist");
        _;
    }

    // ------------------ User Registration --------------------

    function registerPatient(
        address user,
        string memory name,
        uint age,
        string memory gender,
        string memory nationalId
    ) public onlyAdmin {
        require(roles[user] == Role.None, "Already registered");
        roles[user] = Role.Patient;
        patients[user] = PatientInfo(name, age, gender, nationalId);
        emit Registered(user, Role.Patient);
    }

    function registerDoctor(
        address user,
        string memory name,
        string memory specialization,
        string memory licenseId,
        string memory hospitalName
    ) public onlyAdmin {
        require(roles[user] == Role.None, "Already registered");
        roles[user] = Role.Doctor;
        doctors[user] = DoctorInfo(name, specialization, licenseId, hospitalName);
        emit Registered(user, Role.Doctor);
    }

    function registerAdmin(
        address user,
        string memory name,
        string memory organization
    ) public onlyAdmin {
        require(roles[user] == Role.None, "Already registered");
        roles[user] = Role.Admin;
        admins[user] = AdminInfo(name, organization);
        emit Registered(user, Role.Admin);
    }

    // ------------------ Record Management --------------------

    function uploadRecord(string memory ipfsHash) public onlyPatient returns (uint) {
        recordCount++;
        records[recordCount] = Record(ipfsHash, msg.sender, true);
        emit RecordUploaded(recordCount, msg.sender, ipfsHash);
        return recordCount;
    }

    function deleteRecord(uint recordId) public onlyOwner(recordId) recordExists(recordId) {
        delete records[recordId];
        emit RecordDeleted(recordId, msg.sender);
    }

    // ------------------ Access Management --------------------

    function grantAccess(uint recordId, address doctor, uint expiryTime)
        public
        onlyOwner(recordId)
        recordExists(recordId)
    {
        require(roles[doctor] == Role.Doctor, "Target must be a doctor");
        require(expiryTime > block.timestamp, "Expiry must be in the future");

        accessControl[recordId][doctor] = expiryTime;
        doctorAccessibleRecords[doctor].push(recordId);
        emit AccessGranted(recordId, doctor, expiryTime);
    }

    function revokeAccess(uint recordId, address doctor)
        public
        onlyOwner(recordId)
        recordExists(recordId)
    {
        require(accessControl[recordId][doctor] != 0, "Doctor doesn't have access");

        accessControl[recordId][doctor] = 0;
        emit AccessRevoked(recordId, doctor);
    }

    function extendAccess(uint recordId, address doctor, uint newExpiry)
        public
        onlyOwner(recordId)
        recordExists(recordId)
    {
        require(newExpiry > accessControl[recordId][doctor], "New expiry must be later");
        accessControl[recordId][doctor] = newExpiry;
        emit AccessGranted(recordId, doctor, newExpiry);
    }

    function canAccess(uint recordId, address requester)
        public
        view
        recordExists(recordId)
        returns (bool)
    {
        if (requester == records[recordId].owner) return true;
        return (block.timestamp <= accessControl[recordId][requester]);
    }

    function getRecord(uint recordId)
        public
        view
        recordExists(recordId)
        returns (string memory)
    {
        require(canAccess(recordId, msg.sender), "Access denied");
        return records[recordId].ipfsHash;
    }

    function listAccessibleRecords() public view onlyDoctor returns (uint[] memory) {
        uint[] memory all = doctorAccessibleRecords[msg.sender];
        uint count = 0;

        for (uint i = 0; i < all.length; i++) {
            if (block.timestamp <= accessControl[all[i]][msg.sender]) {
                count++;
            }
        }

        uint[] memory valid = new uint[](count);
        uint j = 0;

        for (uint i = 0; i < all.length; i++) {
            if (block.timestamp <= accessControl[all[i]][msg.sender]) {
                valid[j++] = all[i];
            }
        }

        return valid;
    }
}
